]

print('Checking Linear comments for remaining tickets...')
for tid in remaining_ids:
    comments = call_mcp('mcp_mcpd3a6b998_linear_list_comments', {'issueId': tid})
    print(f'=== {tid} ===')
    print('Comments:', comments)
